// USD per million tokens: input, output, cache read, cache write (5-minute TTL).
// The engine reports tokens, not money, so the cost is an estimate.
const PRICES: [RegExp, [number, number, number, number]][] = [
  [/fable|mythos/, [10, 50, 0.25, 12.5]],
  [/opus-5-5/, [4, 20, 0.2, 5]],
  [/opus/, [5, 25, 0.5, 6.25]],
  [/sonnet/, [2, 10, 0.2, 2.5]],
  [/haiku/, [1, 5, 0.1, 1.25]],
]

// Haiku 5.5 bills a request at the low rate while its prompt stays within 100k tokens, and at 5x past it.
// Its cache rates are not in the price table; 0.1x and 1.25x of input are assumed.
export const CHEAP_TIER = 100_000
const TIERED: [number, number, number, number][] = [
  [0.1, 0.5, 0.01, 0.125],
  [0.5, 2.5, 0.05, 0.625],
]
export const isTiered = (model: string): boolean => /haiku-5-5|^haiku$/i.test(model)

type Usage = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

const priceOf = (model: string): [number, number, number, number] =>
  PRICES.find(([re]) => re.test(model.toLowerCase()))?.[1] ?? [4, 20, 0.2, 5]

export const costOf = (model: string, u: Usage): number => {
  const prompt = (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0)
  const [i, o, r, w] = isTiered(model) ? (TIERED[prompt > CHEAP_TIER ? 1 : 0] ?? [0.1, 0.5, 0.01, 0.125]) : priceOf(model)
  return (
    ((u.input_tokens || 0) * i +
      (u.output_tokens || 0) * o +
      (u.cache_read_input_tokens || 0) * r +
      (u.cache_creation_input_tokens || 0) * w) /
    1e6
  )
}

// What the ctx gauge fills toward: for Haiku 5.5 the 100k cheap tier rather than its 1M window, since
// that is the line that changes the bill; older Haiku's 200k window; 1M for the rest.
export const windowOf = (model: string): number => (isTiered(model) ? CHEAP_TIER : /haiku/i.test(model) ? 200_000 : 1_000_000)

// The 80k and 95k marks a Haiku 5.5 subagent is warned at, once each.
export const TIER_WARN = [80_000, 95_000] as const

// The gauge's label and, from the first mark on, a warning colour.
export const gaugeOf = (a: { model: string; contextTokens: number }): { label: string; color?: string } => {
  if (!isTiered(a.model)) return { label: 'ctx' }
  const color = a.contextTokens >= TIER_WARN[1] ? '#D0453F' : a.contextTokens >= TIER_WARN[0] ? '#BA7517' : undefined
  return { label: 'ctx/100k', color }
}

/**
 * The note for a subagent whose next request will carry about `tokens` (its last request plus the tool result
 * on its way), or none; `level` counts the marks already warned at.
 */
export const tierNote = (model: string, tokens: number, level: number): { note?: string; level: number } => {
  if (!isTiered(model)) return { level }
  const reached = TIER_WARN.filter(t => tokens >= t).length
  if (reached <= level) return { level }
  const used = `${Math.round(tokens / 1000)}k`
  const note =
    reached >= 2
      ? `Context budget: with this result your context is about ${used} tokens, and Haiku 5.5 costs 5x more per request past 100k. Stop here and write your final report: what is done, and what is left for another agent.`
      : `Context budget: with this result your context is about ${used} tokens, and Haiku 5.5 costs 5x more per request past 100k. Finish the item you are on without reading anything large, then report what is done and what is left.`
  return { note, level: reached }
}

/**
 * A tool result's size in tokens, estimated from what the model will read at 3.5 characters a token: dense
 * code runs closer to that than to 4 (a 4-character estimate came out ~6k low on a 750-line Read).
 */
const CHARS_PER_TOKEN = 3.5
export const resultTokens = (result: { text?: string; result?: unknown }): number => {
  if (typeof result.text === 'string') return Math.ceil(result.text.length / CHARS_PER_TOKEN)
  const body = typeof result.result === 'string' ? result.result : JSON.stringify(result.result ?? '')
  return Math.ceil((body ?? '').length / CHARS_PER_TOKEN)
}

// `savvy-careful`, or `savvy-flow:savvy-careful` when the agents ship in a plugin.
const tierOf = (type: string): string => {
  const bare = type.replace(/^[^:]*:/, '')
  const t = bare.replace(/^savvy-/, '').toLowerCase()
  return t in TIER_COLOR && bare.startsWith('savvy-') ? t : 'other'
}

// Known agent types first, then words in the type, then words in the task.
const ROLE_BY_TYPE: Record<string, string> = {
  scout: 'explorer',
  architect: 'architect',
  builder: 'handyman',
  worker: 'worker',
  reviewer: 'reviewer',
  tester: 'scientist',
  explore: 'explorer',
  plan: 'architect',
  'general-purpose': 'handyman',
  claude: 'handyman',
  fork: 'handyman',
