  'statusline-setup': 'painter',
  'agent-creator': 'wizard',
  'plugin-validator': 'scientist',
  'skill-reviewer': 'reviewer',
}

const GENERIC = new Set(['general-purpose', 'claude', 'fork'])

const ROLE_WORDS: [RegExp, string][] = [
  [/secur|vuln|pentest|threat|auth/, 'knight'],
  [/review|audit|critique|lint|feedback/, 'reviewer'],
  [/debug|bug|fix|error|crash|trace|diagnos/, 'bugcatcher'],
  [/test|valid|verif|\bqa\b|check|benchmark|eval/, 'scientist'],
  [/plan|design|architect|spec|strateg/, 'architect'],
  [/explor|search|find|locate|scan|scout|research|investig|look|survey|map/, 'explorer'],
  [/style|theme|colou?r|\bui\b|css|statusline|status line|paint|visual|frontend/, 'painter'],
  [/doc|write|readme|draft|summar|explain|guide|copy|note/, 'scribe'],
  [/creat|generat|scaffold|new |make|invent/, 'wizard'],
  [/runner|mechanic|apply|build|implement|run /, 'handyman'],
  [/learn|read|study|answer|question|lookup/, 'librarian'],
]

export const costumeOf = (type: string, description = ''): string => {
  const set = looks[type]
  if (set) return set
  const tier = tierOf(type)
  if (tier !== 'other') return tier
  const bare = type.replace(/^[^:]*:/, '').toLowerCase()
  // A generic worker dresses for the task it was given; a specialist for what it is.
  if (GENERIC.has(bare)) {
    for (const [re, role] of ROLE_WORDS) if (re.test(description.toLowerCase())) return role
    return looks['*'] ?? 'handyman'
  }
  if (ROLE_BY_TYPE[bare]) return ROLE_BY_TYPE[bare] ?? 'handyman'
  if (looks['*'] && !purposes[type]) return looks['*']
  for (const text of [bare.replace(/[-_]/g, ' '), description.toLowerCase(), (purposes[type] ?? '').toLowerCase()])
    for (const [re, role] of ROLE_WORDS) if (re.test(text)) return role
  return 'handyman'
}

const modelName = (id: string): string => {
  const m = /(fable|mythos|opus|sonnet|haiku)-(\d+)(?:-(\d{1,2})(?!\d))?/i.exec(id)
  const [, family = '', major = '', minor] = m ?? []
  if (!family) return id.replace(/^claude-/, '').replace(/\[.*\]$/, '') || '—'
  return `${family.charAt(0).toUpperCase()}${family.slice(1).toLowerCase()} ${major}${minor ? '.' + minor : ''}`
}

const norm = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim()

const fmtTokens = (n: number): string =>
  n >= 1e6 ? `${(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${Math.round(n / 1e3)}k` : `${Math.round(n)}`

const fmtCost = (usd: number): string => `$${usd < 10 ? usd.toFixed(2) : usd.toFixed(1)}`

const fmtTime = (ms: number): string => {
  const s = Math.max(0, Math.round(ms / 1000))
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const ss = String(s % 60).padStart(2, '0')
  return h ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`
}

const elapsed = (a: AgentRun, at: number): number => (a.endedAt ?? Math.max(at, a.startedAt)) - a.startedAt

type Planned = PlannedTask & { n: number }

const plannedOf = (f: Flow | null, list: AgentRun[]): Planned[] => {
  if (!f || f.isFinished) return []
  const started = new Set(list.map(a => norm(a.description)))
  return (f.tasks ?? []).map((t, i) => ({ ...t, n: i + 1 })).filter(t => !started.has(norm(t.title)))
}

const totals = (list: AgentRun[], at: number) => {
  const cost = list.reduce((s, a) => s + a.costUsd, 0)
  const tokens = list.reduce((s, a) => s + a.tokens, 0)
  const start = Math.min(...list.map(a => a.startedAt))
  const end = Math.max(...list.map(a => a.endedAt ?? Math.max(at, a.startedAt)))
  return { cost, tokens, time: list.length ? end - start : 0 }
}

