export const seedSavvyRoles = (s: CrewSettings): CrewSettings => {
  const roles = { ...s.roles }
  for (const r of SAVVY_ROLES) if (!roles[r.name]) roles[r.name] = { ...DEFAULT_ROLE, model: r.model, effort: r.effort }
  return { ...s, roles, isSavvyOnly: true }
}

