files.types/index.d.ts:
export type FileNode = {
  id: string
  parent: string
  name: string
  kind: 'dir' | 'file' | 'link'
  hidden: boolean
  mtime: number
  size: number
  loaded: boolean
}

export type Branch = {
  head: string
  upstream: string
  ahead: number
  behind: number
}

export type Activity = {
  id: number
  kind: string
  label: string
  state: 'running' | 'done' | 'failed'
  detail: string
  at: number
  tone: string
  nerd: string
  plain: string
}

export type FileTree = {
  root: string
  nodes: FileNode[]
  expanded: string[]
  cursor: string
  selected: string
  query: string
  showHidden: boolean
  showSize: boolean
  dirSizes: Record<string, number>
  git: Record<string, string>
  diff: Record<string, [number, number]>
  ignored: string[]
  untrackedDirs: string[]
  top: string
  prefix: string
  branch: Branch | null
  counts: Record<string, [number, number, number]>
  flash: string[]
  flashDim: string[]
  flashOn: boolean
  flashTones: Record<string, string>
  scroll: number | null
}

export type Theme = {
  fg: string
  accent: string
  muted: string
  urgent: string
  selection: string
  bg: string
}


export type StripState = {
  top: string
  branches: { name: string; isCurrent: boolean }[]
  sweepable: string[]
  isSweeping: boolean
  isReloading: boolean
  /** False where `/reload-plugins` is refused (a desktop-app or other remote session); the Reload button hides. */
  canReload: boolean
  /** Uncommitted changes in the repo (`git status --porcelain` lines); 0 when clean or not a repo. */
  changes: number
  /** The person's open PRs for this repo (`gh pr list --author @me`); [] when gh fails. */
  prs: StripPr[]
}

/** One plan window as the usage band shows it: the 5-hour or the 7-day, as a whole percent used. */
export type UsageLimit = {
  label: '5h' | '7d'
  percent: number
  /** When the window resets, epoch ms; absent when the engine reported no time. */
  resetsAt?: number
}

export type StripPr = {
  number: number
  title: string
  branch: string
  url: string
  checks: 'passing' | 'failing' | 'pending' | 'none'
}

export type Phase = 'plan' | 'design' | 'delegate' | 'review' | 'close'

export type PlannedTask = {
  title: string
  tier: string
  after: number[]
}

export type Flow = {
  title: string
  total: number
  done: number
  running: number
  phase: Phase
  isFinished: boolean
  tasks: PlannedTask[]
}

export type AgentStatus = 'running' | 'done' | 'failed'

export type AgentRun = {
  id: string
  agentId?: string
  type: string
  description: string
  model: string
  effort?: string
  status: AgentStatus
  startedAt: number
  endedAt?: number
  contextTokens: number
  contextMax: number
  tokens: number
  costUsd: number
  steps: number
  round: number
  /** Self-reported by the worker through the `step` tool. */
  stepDone?: number
  stepTotal?: number
  stepNote?: string
}

export type Panel = {
  isCompact: boolean
  isDoneCollapsed: boolean
  autoOpenedFor: string
  /** Which controls tab is open under Sub-agents; '' for none. */
  crewTab?: '' | 'roles' | 'defaults' | 'rules'
  /** Cards opened by a click on their crab: 'main', an agent's id, or 'settings'. */
  openCards?: string[]
}

/** A model choice for a role: `default` leaves the agent's own choice alone. */
export type ModelChoice = 'default' | 'inherit' | 'haiku' | 'sonnet' | 'opus' | 'fable'

/** An effort choice for a role: `default` leaves the agent's own effort alone. */
export type EffortChoice = 'default' | 'low' | 'medium' | 'high' | 'xhigh' | 'max'

/** What one agent type is set to. */
export type RoleSetting = {
  model: ModelChoice
  effort: EffortChoice
  isAllowed: boolean
  /** The crab's costume for this role; `auto` picks one from the type and task. */
  costume?: string
}

/** Delegation for a session: `turn` is on until the next reply finishes. */
export type SessionMode = 'on' | 'off' | 'turn'

/** Settings kept across sessions (also written to the mod store). */
export type CrewSettings = {
  /** Delegation for a new session. */
  defaultMode: 'on' | 'off'
  /** Also block the Workflow tool while delegation is off. */
  isGatingWorkflows: boolean
  /** Per agent type. */
  roles: Record<string, RoleSetting>
  /** For any agent type with no row of its own. */
  fallback: RoleSetting
  /** Replace a model the Agent call itself names. */
  isOverridingCallModel: boolean
  /** Most subagents running at once; 0 is no limit. */
  maxRunning: number
  /** Offer and allow only the Savvy Status roles (savvy-status:*), hiding every other agent type. */
  isSavvyOnly: boolean
  /** Orchestration rules Claude reads while delegation is on. */
  rules: string[]
}

/** One file an agent read or wrote, for its hover tree. */
export type Touch = { path: string; tone: string; at: number }

/** An agent type Claude Code has offered (built-in, user, project or plugin). */
export type KnownAgent = { name: string; source: string; description: string }

/** The session's delegation switch. */
export type ModeState = { mode: SessionMode; hasTurnStarted: boolean }

declare module 'claude-code' {
  interface PluginState {
    'savvy-status': {
      tree: FileTree
      theme: Theme
      activity: Activity[]
      flow: Flow | null
      agents: AgentRun[]
      panel: Panel
      now: number
      crewSettings: CrewSettings
      crewMode: ModeState
      crewAgents: KnownAgent[]
      /** Files each loop touched, keyed by agentId; `main` is the main loop. */
      touches: Record<string, Touch[]>
      /** The main loop drawn as a row of its own above the sub-agents. */
      mainRun: AgentRun
      /** The strip above Main Agent: local branches, which a merge sweep would delete, and what is running. */
      strip: StripState
      /** The plan's 5h and 7d windows, for the usage band at the top of the pane; [] off a subscription. */
      usage: UsageLimit[]
    }
  }
}
